create table if not exists tka_attempts (attempt_id uuid primary key, session_id uuid not null references tka_sessions(session_id), student_id uuid not null references student_identities(student_id), package_index integer not null check(package_index between 1 and 5), started_at timestamptz not null, expires_at timestamptz not null, submitted_at timestamptz, status text not null default 'IN_PROGRESS');
create unique index if not exists uq_tka_active_attempt on tka_attempts(session_id,student_id) where status='IN_PROGRESS';
create table if not exists tka_answers (answer_id uuid primary key, attempt_id uuid not null references tka_attempts(attempt_id), question_id uuid not null references tka_questions(question_id), answer jsonb, revision integer not null default 1, updated_at timestamptz not null default now(), unique(attempt_id,question_id));
